        reportKey: 'idle_10s'); // expect ~0 frames when nothing animates
  });
}

// trader_core: utils/perf/perf_tracer.dart
abstract class PerfTracer {
  void start(String name);
  void stop(String name, {Map<String, Object?> attributes = const <String, Object?>{}});
}
class NoopPerfTracer implements PerfTracer {
  const NoopPerfTracer();
  @override void start(String name) {}
  @override void stop(String name, {Map<String, Object?> attributes = const {}}) {}
}

// super_app
class DatadogPerfTracer implements PerfTracer {
  final Map<String, int> _t0 = <String, int>{};
  @override void start(String name) => _t0[name] = DateTime.now().microsecondsSinceEpoch;
  @override void stop(String name, {Map<String, Object?> attributes = const {}}) {
    final int? t0 = _t0.remove(name);
    if (t0 == null) return;
    final double ms = (DateTime.now().microsecondsSinceEpoch - t0) / 1000;
    DatadogSdk.instance.rum?.addAction(RumActionType.custom, name,
        <String, Object?>{...attributes, 'duration_ms': ms}); // or addTiming - verify API
  }
}

